#!/usr/bin/env bash
# Generated by fff --setup file-chooser; running it again regenerates this file.
#
# xdg-desktop-portal-termfilechooser runs this for every file dialog with
#   MULTIPLE DIRECTORY SAVE PATH OUT [LOGLEVEL]
# MULTIPLE is 1 when several files may be chosen, DIRECTORY 1 when a
# directory is wanted and SAVE 1 when saving, with PATH the suggested file
# (otherwise a starting place, possibly empty). The chosen paths go to OUT,
# one per line; leaving it empty cancels the dialog. From LOGLEVEL 4 (debug)
# on, the script traces its commands. `fff explorer` does the choosing; this
# script translates the arguments and opens a terminal.
#
# fff opens in a new terminal window: the terminal below is [open]
# fff_terminal from fff's configuration at setup time, and TERMCMD overrides it.

fff=@FFF@
if [[ -n ${TERMCMD:-} ]]; then
    read -r -a terminal <<<"$TERMCMD"
else
    terminal=(@TERMINAL@)
fi

if [[ ${1:-} != --in-terminal ]]; then
    # The terminal's own messages (st logs every escape sequence it does not
    # support) would fill the portal's log; keep them only when debugging.
    if [[ ${6:-0} -ge 4 ]]; then
        set -x
        exec "${terminal[@]}" "$0" --in-terminal "$@"
    fi
    exec "${terminal[@]}" "$0" --in-terminal "$@" >/dev/null 2>&1
fi
shift
multiple=$1 directory=$2 save=$3 path=$4 out=$5
[[ ${6:-0} -ge 4 ]] && set -x

args=(explorer)
[[ $multiple == 1 ]] && args+=(--multiple)
[[ $directory == 1 ]] && args+=(--directory)
[[ $save == 1 ]] && args+=(--save)
[[ -n $path ]] && args+=("$path")
# Without a suggestion, dialogs start at home.
cd -- "$HOME" || exit
"$fff" "${args[@]}" >"$out"
exit 0
